const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={pages:[],assets:[],jobs:[]},selected=new Set(),plan=null;
const labels={scheduled:'Đã lên lịch',starting:'Tạo phiên đăng',uploading:'Đang tải lên',finishing:'Gửi yêu cầu xuất bản',checking:'Đợi Meta xác nhận',published:'Đã đăng',review:'Cần đối soát',failed:'Lỗi',missed:'Quá giờ',cancelled:'Đã hủy'};
function notice(text,error=false){$('#notice').hidden=false;$('#notice').textContent=text;$('#notice').className=error?'error':'';const dialog=$('#page-workspace');if(dialog?.open){let message=$('#workspace-notice');if(!message){message=document.createElement('p');message.id='workspace-notice';message.setAttribute('role','status');dialog.insertBefore(message,dialog.children[1]);}message.textContent=text;message.className=error?'danger':'hint';message.scrollIntoView({behavior:'smooth',block:'nearest'});}else $('#notice').scrollIntoView({behavior:'smooth',block:'nearest'});}
async function api(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'X-Story-Client':'publisher',...(body instanceof FormData?{}:{'Content-Type':'application/json'})},body:body instanceof FormData?body:JSON.stringify(body)});const b=await r.json();if(!r.ok)throw Error(b.error||'Kết nối lỗi');return b;}
async function guard(fn){try{await fn();}catch(e){notice(e.message,true);}}
function invalidate(){plan=null;$('#plan').innerHTML='';$('#commit').hidden=true;}
function timePair(at,pageId){const p=state.pages.find(p=>p.id===pageId),market=state.countries?.[p?.country];return PublisherTime.pair(at,market?.[1]||p?.zone||PublisherTime.zone,market?.[0]||'Quốc gia Page');}
function manualComparison(){const box=$('#manual-comparison');if(!box)return;try{box.textContent=$('#manual').value?timePair(PublisherTime.inputISO($('#manual').value),$('#target-page').value):'Nhập giờ Việt Nam để đối chiếu giờ quốc gia Page (tự đổi giờ mùa hè).';}catch{box.textContent='Chọn ngày giờ hợp lệ.';}}
function pageInfo(){const p=state.pages.find(p=>p.id===$('#target-page').value);$('#page-info').textContent=p?`${p.name} · ${p.zone} · ${p.slots.join(' / ')}${p.connected?'':' · Chưa kết nối token'}`:'Thêm Page trong mục Page & khung giờ.';}
let assetPage=1,queueView='list',discoverySession=null;
const pageStatus={missing:['Chưa kết nối','warn'],error:['Kết nối lỗi','warn'],permissions:['Thiếu quyền','warn'],stale:['Cần kiểm tra lại','warn'],verified:['Đã xác thực Page','ok']};
function connectionBadge(p){const [title,cls]=pageStatus[p.connection?.status||'missing'];return `<span class="pill ${cls}">${title}</span>`;}
function options(target,pages){const old=target.value;target.innerHTML='<option value="">'+(target.id==='job-page'?'Mọi Page':'Chọn Page')+'</option>'+pages.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}${p.enabled?'':' · Tạm dừng'}</option>`).join('');target.value=old;}
function render(){
 options($('#target-page'),state.pages);options($('#job-page'),state.pages);pageInfo();renderStats();renderAssets();renderPages();renderJobs();renderOverview();renderPageWorkspace();
 $('#telegram-state').textContent=state.telegram?'● Bot đã được cấu hình':'Chưa kết nối bot thông báo.';
 $('#meta-count').textContent=state.pages.length+' Page trong workspace';
 $('#notifications').innerHTML=(state.notifications||[]).map(n=>`<div class="notification"><span class="pill ${n.status==='sent'?'ok':n.status==='failed'?'warn':''}">${({sent:'Đã gửi',pending:'Chờ gửi',sending:'Đang gửi',failed:'Gửi thất bại'})[n.status]||esc(n.status)}</span><small>${n.attempts} lần thử${n.error?' · '+esc(n.error):''}</small></div>`).join('');
}
function renderStats(){
 const surface=document.querySelector('nav button.active')?.dataset.tab,page=surface==='overview'?dashboardPage():surface==='library'&&state.pages.some(p=>p.id===$('#library-page').value)?$('#library-page').value:'',viewJobs=state.jobs.filter(j=>!page||j.page_id===page),viewAssets=state.assets.filter(a=>!page||a.page_id===page),viewPages=state.pages.filter(p=>!page||p.id===page),pending=viewJobs.filter(j=>j.status==='scheduled').length,published=viewJobs.filter(j=>j.published_at).length;
 $('#stats').innerHTML=[[viewAssets.length,'Tổng video của Page','▤',`${viewAssets.length-published} chưa đăng · ${published} đã đăng`],[pending,'Lịch chờ đăng','▦','Giờ Việt Nam · đúng từng phút'],[published,'Đã xuất bản','↗','Được Meta xác nhận'],[viewPages.filter(p=>p.connection?.status==='verified').length,'Page đã xác thực','◎','Danh tính token đã kiểm tra']].map(([n,t,icon,sub])=>`<div class="stat"><div class="stat-top"><span>${t}</span><i>${icon}</i></div><b>${n}</b><small>${sub}</small></div>`).join('');
 $('#nav-assets').textContent=state.assets.length;$('#nav-jobs').textContent=state.jobs.filter(j=>j.status==='scheduled').length;$('#nav-alert').textContent=state.pages.filter(p=>p.connection?.status!=='verified').length||'';
}
function filteredAssets(){const q=$('#asset-search').value.toLowerCase().trim(),f=$('#asset-filter').value;return state.assets.filter(a=>(!$('#library-page').value||($('#library-page').value==='unassigned'?!a.page_id:a.page_id===$('#library-page').value))&&(a.name+' '+a.title+' '+a.caption).toLowerCase().includes(q)&&(f==='all'||f==='ready'&&a.caption||f==='missing'&&!a.caption||f==='unused'&&!state.jobs.some(j=>j.asset_id===a.id&&j.status!=='cancelled')));}
function selectionInfo(){const n=selected.size;$('#selected-count').textContent=n?`${n} video được chọn`:'Chưa chọn video';$('#planner-selection').textContent=n+' video được chọn';$('#preview-plan').disabled=!n;}
function renderAssets(){
 for(const id of selected){const a=state.assets.find(a=>a.id===id);if(!a||assetHasJob(a))selected.delete(id);}
 const pageSize=12,found=filteredAssets(),pages=Math.max(1,Math.ceil(found.length/pageSize));assetPage=Math.min(assetPage,pages);const visible=found.slice((assetPage-1)*pageSize,assetPage*pageSize);
 $('#result-count').textContent=found.length+' video';$('#asset-page').textContent=`Trang ${assetPage} / ${pages}`;$('#prev-assets').disabled=assetPage<=1;$('#next-assets').disabled=assetPage>=pages;selectionInfo();$('#select-all').disabled=!found.some(a=>!assetHasJob(a));$('#select-all').textContent='Chọn video chưa có lịch';
 $('#assets').innerHTML=visible.length?visible.map(a=>`<div class="asset ${selected.has(a.id)?'selected':''}"><div class="asset-cover"><video src="/media/${a.id}#t=0.1" muted preload="metadata" aria-label="Ảnh xem trước ${esc(a.title||a.name)}"></video><input aria-label="Chọn ${esc(a.name)}" type="checkbox" data-select="${a.id}" ${selected.has(a.id)?'checked':''} ${assetHasJob(a)?'disabled title="Video đã có lịch/bài, dùng Đổi giờ để điều chỉnh"':''}><button class="preview-button" data-edit="${a.id}" aria-label="Xem ${esc(a.title||a.name)}">▷</button><span class="cover-label">REEL · MP4</span></div><div class="asset-body"><strong>${esc(a.title||a.name)}</strong><small class="file-name" title="${esc(a.name)}">${esc(a.name)}</small><p class="caption">${esc(a.caption||'Chưa có caption — hãy bổ sung trước khi lên lịch.')}</p><small>${esc(state.pages.find(p=>p.id===a.page_id)?.name||'Chưa gán Page')}</small>${assetSchedule(a)}<div class="asset-tags"><span class="pill ${a.caption?'ok':'warn'}">${a.caption?'✓ Caption':'Thiếu caption'}</span><span class="pill">${a.comment?'Có bình luận':'Không bình luận'}</span></div><div class="actions">${canPublishNow(a)?`<button class="secondary compact" data-publish-now="${a.id}">Đăng ngay</button>`:''}<button class="text-button" data-edit="${a.id}">Xem & chỉnh sửa</button><button class="text-button danger" data-delete="${a.id}" aria-label="Xóa ${esc(a.name)}">Xóa</button></div></div></div>`).join(''):'<div class="empty"><b>Không có video phù hợp</b>Đổi bộ lọc hoặc nhập ZIP từ Video Studio.</div>';
}
function renderPageCards(){
 $('#pages-list').innerHTML=state.pages.length?state.pages.map(p=>`<div class="page-card"><div class="row"><div class="page-identity"><span class="page-avatar">${esc(p.name.slice(0,1))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.id)} · ${esc(p.country)}</small></div></div>${connectionBadge(p)}</div><div class="page-time"><b>${esc(p.zone)}</b><div>${p.slots.map(t=>`<span class="time-chip">${esc(t)}</span>`).join('')}</div></div><p class="hint">${p.connection?.livePublished?'✓ Đã có bài đăng thật được Meta xác nhận.':'Chưa xác minh bằng bài đăng thật.'}${p.enabled?'':' · Page đang tạm dừng.'}</p>${p.connection?.error?`<p class="danger">${esc(p.connection.error)}</p>`:''}${p.connection?.missing?.length?`<p class="danger">Thiếu: ${esc(p.connection.missing.join(', '))}</p>`:''}<details><summary>Chi tiết kết nối & quyền</summary><p class="hint">Kiểm tra gần nhất: ${p.verified_at?new Date(p.verified_at).toLocaleString('vi-VN'):'chưa kiểm tra'}<br>Quyền tạo nội dung theo tasks: ${p.connection?.canCreate===null?'chưa có dữ liệu':p.connection?.canCreate?'có':'chưa được cấp'}<br>Quyền bình luận: ${p.connection?.commentPermission===null?'chưa có dữ liệu':p.connection?.commentPermission?'có':'chưa được cấp'}<br>Scopes: ${esc(p.connection?.scopes?.join(', ')||'Chưa đọc được. Kết nối bằng User Token để lấy thông tin.')}</p></details><div class="actions"><button class="secondary compact" data-page-edit="${p.id}">Sửa khung giờ</button><button class="secondary compact" data-page-action="verify" data-id="${p.id}">Kiểm tra</button><button class="secondary compact" data-page-action="toggle" data-id="${p.id}">${p.enabled?'Tạm dừng':'Bật Page'}</button><button class="text-button danger" data-page-action="delete" data-id="${p.id}">Xóa</button></div></div>`).join(''):'<div class="empty"><span class="empty-icon">◎</span><b>Chưa có Page nào</b>Kết nối tài khoản để chọn các Page bạn quản lý.<br><button data-goto="connect">Kết nối Page →</button></div>';
}
function renderPages(){renderPageCards();renderFacebookNames();renderPageSettingsButtons();}
function renderFacebookNames(){document.querySelectorAll('#pages-list .page-card').forEach((card,i)=>{const p=state.pages[i];if(p?.facebookName&&p.facebookName.trim()!==p.name.trim()){const note=document.createElement('p');note.className='hint';note.textContent='Tên thực tế trên Facebook: '+p.facebookName+' · Tên phía trên là nhãn quản lý mới trong tool.';card.insertBefore(note,card.querySelector('.page-time'));}});}
function filteredJobs(){const q=$('#job-search').value.toLowerCase().trim(),filter=$('#job-filter').value,p=$('#job-page').value;return state.jobs.filter(j=>(!$('#job-date').value||new Date(j.scheduled_at).toLocaleDateString('sv-SE')===$('#job-date').value)&&(j.page_name+' '+j.title).toLowerCase().includes(q)&&(!p||j.page_id===p)&&(filter==='all'||filter==='processing'&&['starting','uploading','finishing','checking'].includes(j.status)||filter==='attention'&&['review','failed','missed'].includes(j.status)||filter===j.status));}
function jobCard(j){return `<div class="job"><div class="row"><div><small class="eyebrow">${esc(j.page_name)}</small><h3>${esc(j.title||state.assets.find(a=>a.id===j.asset_id)?.name||'Video')}</h3></div><span class="pill ${j.status==='published'?'ok':['review','failed','missed'].includes(j.status)?'warn':''}">${labels[j.status]||esc(j.status)}</span></div><p class="job-time">◷ ${esc(timePair(j.scheduled_at,j.page_id))}</p>${j.status==='published'?`<p class="hint">${j.view_count===null||j.view_count===undefined?'Lượt xem: chờ cập nhật':`${Number(j.view_count).toLocaleString('vi-VN')} lượt xem`}${j.views_alert_at?' · Đã đạt mốc 1.000': ' · Báo Telegram khi đạt 1.000'}${j.views_error?' · Chưa đọc được lượt xem: '+esc(j.views_error):''}</p>`:''}${j.error?`<p class="error-inline">${esc(j.error)}</p>`:''}${j.comment?`<p class="hint">Bình luận: ${esc({pending:'chờ xuất bản',sending:'đang gửi',sent:'đã gửi',review:'cần kiểm tra trên Facebook'}[j.comment_state])}</p>`:''}<div class="actions">${['scheduled','missed'].includes(j.status)?`<button class="secondary compact" data-reschedule="${j.id}">Đổi giờ</button><button class="text-button danger" data-job="cancel" data-id="${j.id}">Hủy lịch</button>`:''}${['missed','failed'].includes(j.status)&&!j.video_id?`<button class="secondary compact" data-job="retry" data-id="${j.id}">Đăng ngay</button>`:''}${j.video_id?`<a class="button secondary compact" href="https://www.facebook.com/reel/${encodeURIComponent(j.video_id)}" target="_blank" rel="noopener">Mở bài ↗</a><button class="text-button" data-job="check" data-id="${j.id}">Đối soát Meta</button>`:''}</div></div>`;}
function renderJobs(){const jobs=filteredJobs();$('#job-count').textContent=jobs.length+' kết quả · giờ Việt Nam ↔ giờ quốc gia Page';if(!jobs.length)$('#jobs').innerHTML='<div class="empty"><span class="empty-icon">▦</span><b>Chưa có lịch phù hợp</b>Lịch sẽ xuất hiện sau khi bạn chọn Page và xác nhận thời gian đăng.</div>';else if(queueView==='list')$('#jobs').innerHTML=jobs.map(jobCard).join('');else {const groups=new Map();for(const j of [...jobs].sort((a,b)=>a.scheduled_at.localeCompare(b.scheduled_at))){const key=new Date(j.scheduled_at).toLocaleDateString('sv-SE',{timeZone:j.zone})+' · '+j.zone;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(j);}$('#jobs').innerHTML=[...groups].map(([day,items])=>`<div class="day-group"><h3>${esc(day)} <span class="pill">${items.length} bài</span></h3>${items.map(jobCard).join('')}</div>`).join('');}$('#events').innerHTML=(state.events||[]).map(e=>`<p>${new Date(e.time).toLocaleString('vi-VN')} · ${esc(e.message)}</p>`).join('')||'<p class="hint">Chưa có hoạt động đăng bài.</p>';}
function renderOverview(){
 renderCalendarDashboard();
 $('#local-clock').textContent=new Date().toLocaleDateString('vi-VN',{day:'2-digit',month:'long'});
 $('#readiness').innerHTML=[['Máy đăng','Đang chạy trên máy này',true],['Facebook',state.pages.length?`${state.pages.filter(p=>p.connection?.status==='verified').length}/${state.pages.length} Page xác thực danh tính`:'Cần kết nối Page',state.pages.some(p=>p.connection?.status==='verified')],['Telegram',state.telegram?'Đã cấu hình bot':'Chưa kết nối',state.telegram]].map(([title,sub,ok])=>`<div class="readiness-item"><span class="status-dot ${ok?'good':''}"></span><div><b>${title}</b><small>${sub}</small></div><span>${ok?'✓':'→'}</span></div>`).join('');
 const upcoming=state.jobs.filter(j=>j.status==='scheduled'&&(!dashboardPage()||j.page_id===dashboardPage())).sort((a,b)=>a.scheduled_at.localeCompare(b.scheduled_at)).slice(0,4);
 $('#upcoming').innerHTML=upcoming.length?upcoming.map(j=>`<div class="mini-item"><b>${esc(j.title||'Video')}</b><small>${esc(j.page_name)} · ${esc(timePair(j.scheduled_at,j.page_id))}</small></div>`).join(''):'<div class="empty small"><b>Hàng đợi đang trống</b>Video đã nhập sẽ được giữ trong kho cho đến khi bạn xác nhận lịch.</div>';
 const issues=state.jobs.filter(j=>['failed','review','missed'].includes(j.status)||j.comment_state==='review');
 $('#attention').innerHTML=(!state.pages.length?'<div class="mini-item"><b>Kết nối Page đầu tiên</b><small>Chọn Page của bạn để bắt đầu xếp lịch.</small><button class="text-button" data-goto="connect">Đi đến kết nối →</button></div>':'')+issues.slice(0,5).map(j=>`<div class="mini-item"><b>${esc(j.page_name)} · ${labels[j.status]}</b><small>${esc(j.error||'Bình luận cần kiểm tra.')}</small></div>`).join('')||'<div class="empty small"><b>Không có lỗi cần xử lý</b>Các cảnh báo về bài đăng sẽ xuất hiện tại đây.</div>';
}
async function refresh(){state=await api('/api/state');$('#health').textContent='● Máy đăng đang hoạt động';render();}
function planBody(){return {pageId:$('#target-page').value,assetIds:[...selected],mode:$('#mode').value,...($('#mode').value==='manual'?{at:PublisherTime.inputISO($('#manual').value)}:{})};}
function resetPage(){$('#page-form').reset();$('#page-form').elements.id.readOnly=false;$('#page-form-title').textContent='Thêm Page Facebook';$('#zone').value=PublisherTime.zone;}
$('nav').onclick=e=>{const button=e.target.closest('[data-tab]');if(button)navigate(button.dataset.tab);};
$('#files').onchange=()=>guard(async()=>{await uploadPageFiles($('#files').files,$('#library-page').value,$('#library-auto').checked);$('#files').value='';});
$('#assets').onchange=e=>{const id=e.target.dataset.select;if(!id)return;const a=state.assets.find(a=>a.id===id);if(e.target.checked&&a?.page_id&&$('#target-page').value!==a.page_id){selected.clear();$('#target-page').value=a.page_id;pageInfo();}e.target.checked?selected.add(id):selected.delete(id);invalidate();e.target.closest('.asset').classList.toggle('selected',e.target.checked);selectionInfo();};
$('#assets').onclick=e=>guard(async()=>{const edit=e.target.dataset.edit,del=e.target.dataset.delete;if(edit){const a=state.assets.find(x=>x.id===edit),form=$('#asset-form');for(const key of ['id','title','caption','comment'])form.elements[key].value=a[key]||'';$('#video').src='/media/'+a.id;$('#editor').showModal();}if(del&&confirm('Xóa video khỏi kho Publisher?')){await api('/api/assets',{id:del,delete:true});selected.delete(del);invalidate();await refresh();}});
$('#select-all').onclick=()=>{for(const a of filteredAssets().filter(a=>!assetHasJob(a)))selected.add(a.id);invalidate();renderAssets();};
$('#close-editor').onclick=()=>{$('#video').pause();$('#editor').close();};$('#editor').onclose=()=>$('#video').pause();
$('#asset-form').onsubmit=e=>{e.preventDefault();guard(async()=>{await api('/api/assets',Object.fromEntries(new FormData(e.target)));$('#editor').close();invalidate();await refresh();notice('Đã lưu caption và bình luận.');});};
$('#target-page').onchange=()=>{invalidate();pageInfo();manualComparison();};$('#mode').onchange=()=>{$('#manual-wrap').hidden=$('#mode').value!=='manual';invalidate();manualComparison();};$('#manual').oninput=()=>{invalidate();manualComparison();};
$('#preview-plan').onclick=()=>guard(async()=>{plan=await api('/api/plan',planBody());$('#plan').innerHTML=plan.items.map(x=>`<div class="plan-item"><b>${esc(x.name)}</b><p>${esc(timePair(x.at,$('#target-page').value))}</p></div>`).join('');$('#commit').hidden=false;$('#commit').textContent=$('#mode').value==='now'?'Xác nhận đăng ngay':'Xác nhận '+plan.items.length+' lịch đăng';});
$('#commit').onclick=()=>guard(async()=>{if(!plan)return;$('#commit').disabled=true;try{const b=await api('/api/schedule',{...planBody(),times:plan.items.map(x=>x.at)});notice(`Đã tạo ${b.count} lịch đăng. Theo dõi tại LỊCH ĐĂNG.`);selected.clear();invalidate();await refresh();}finally{$('#commit').disabled=false;}});
$('#country').onchange=()=>$('#zone').value=PublisherTime.zone;
$('#page-form').onsubmit=e=>{e.preventDefault();guard(async()=>{const b=Object.fromEntries(new FormData(e.target));b.slots=b.slots.split(',').map(x=>x.trim()).filter(Boolean);await api('/api/pages',b);await refresh();resetPage();notice('Đã lưu Page. Lịch đã xác nhận giữ nguyên giờ cũ.');});};$('#reset-page').onclick=resetPage;
$('#pages-list').onclick=e=>guard(async()=>{if(e.target.dataset.pageEdit){const p=state.pages.find(p=>p.id===e.target.dataset.pageEdit),f=$('#page-form');for(const k of ['id','name','country','zone'])f.elements[k].value=p[k];f.elements.slots.value=p.slots.join(', ');f.elements.token.value='';f.elements.id.readOnly=true;$('#page-form-title').textContent='Sửa '+p.name;f.scrollIntoView({behavior:'smooth'});}if(e.target.dataset.pageAction){const action=e.target.dataset.pageAction;if(action==='delete'&&!confirm('Xóa Page này?'))return;await api('/api/page-action',{action,id:e.target.dataset.id});await refresh();notice('Đã cập nhật Page.');}});
$('#jobs').onclick=e=>guard(async()=>{if(!e.target.dataset.job)return;if(e.target.dataset.job==='retry'&&!confirm('Đăng video này ngay bây giờ?'))return;await api('/api/job-action',{id:e.target.dataset.id,action:e.target.dataset.job});await refresh();});
$('#refresh').onclick=()=>guard(refresh);
$('#reuse-telegram').onclick=()=>guard(async()=>{await api('/api/telegram',{action:'reuse'});await refresh();notice('Đã dùng bot và nơi nhận thông báo của Studio.');});
$('#test-telegram').onclick=()=>guard(async()=>{await api('/api/telegram',{action:'test'});notice('Đã đưa thông báo thử vào hàng đợi Telegram.');});
$('#telegram-form').onsubmit=e=>{e.preventDefault();guard(async()=>{await api('/api/telegram',{action:'save',...Object.fromEntries(new FormData(e.target))});e.target.reset();await refresh();notice('Đã lưu cấu hình Telegram.');});};
guard(async()=>{await refresh();$('#country').innerHTML=Object.entries(state.countries).map(([code,[name]])=>`<option value="${code}">${esc(name)}</option>`).join('');$('#discover-country').innerHTML=$('#country').innerHTML;});
let offlineNotified=false;
setInterval(()=>{(async()=>{const latest=await api('/api/state');offlineNotified=false;$('#health').classList.remove('offline');state.assets=latest.assets;state.jobs=latest.jobs;state.events=latest.events;state.pages=latest.pages;state.notifications=latest.notifications;state.telegram=latest.telegram;renderAssets();renderJobs();renderStats();renderOverview();renderPages();renderPageWorkspace();$('#health').textContent='● Máy đăng đang hoạt động';})().catch(()=>{$('#health').textContent='● Mất kết nối máy đăng';$('#health').classList.add('offline');if(!offlineNotified){offlineNotified=true;notice('Mất kết nối máy đăng. Dữ liệu đang hiển thị là lần đồng bộ trước; hãy mở lại Publisher bằng file .command.',true);}});},15000);

function navigate(tab){const names={overview:['Tổng quan','Một nơi cho mọi lịch đăng.','Nội dung, Page và tiến độ xuất bản — mọi thứ trong tầm mắt.'],library:['Kho video','Nội dung tốt, lịch đăng rõ ràng.','Nhập video từ Studio. Chọn nội dung và xếp lịch trong cùng một màn hình.'],queue:['Lịch đăng','Biết bài nào sẽ lên, bài nào đã đăng.','Theo dõi trạng thái thật từ Meta và xử lý lịch cần chú ý.'],pages:['Page & khung giờ','Mỗi Page, một nhịp đăng riêng.','Quản lý thị trường, múi giờ và các khung giờ bạn muốn thử nghiệm.'],connect:['Kết nối','Kết nối rõ ràng. Vận hành chủ động.','Kiểm tra quyền Page và cấu hình thông báo cho workspace của bạn.']};if(!names[tab])return;document.querySelectorAll('.tab').forEach(x=>x.hidden=x.id!==tab);document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));const [name,title,desc]=names[tab];$('#section-label').textContent=name;$('#view-title').textContent=title;$('#view-description').textContent=desc;renderStats();window.scrollTo({top:0,behavior:'smooth'});}
document.addEventListener('click',e=>{const go=e.target.closest('[data-goto]');if(go)navigate(go.dataset.goto);});
$('#sync-all').onclick=()=>guard(async()=>{await refresh();notice('Đã đồng bộ trạng thái từ máy đăng.');});
for(const id of ['asset-search','asset-filter'])$('#'+id).addEventListener('input',()=>{assetPage=1;renderAssets();});
$('#clear-selection').onclick=()=>{selected.clear();invalidate();renderAssets();};$('#prev-assets').onclick=()=>{assetPage--;renderAssets();};$('#next-assets').onclick=()=>{assetPage++;renderAssets();};
for(const id of ['job-search','job-filter','job-page','job-date'])$('#'+id).addEventListener('input',renderJobs);
function switchQueue(view){queueView=view;$('#list-view').classList.toggle('active',view==='list');$('#calendar-view').classList.toggle('active',view==='calendar');renderJobs();}
$('#list-view').onclick=()=>switchQueue('list');$('#calendar-view').onclick=()=>switchQueue('calendar');
$('#week-strip').onclick=e=>{const button=e.target.closest('[data-day]');if(button){$('#timeline-day').value=button.dataset.day;renderCalendarDashboard();}};
function rescheduleComparison(){const f=$('#reschedule-form'),j=state.jobs.find(x=>x.id===f.elements.id.value);if(!j)return;try{$('#reschedule-info').textContent=j.page_name+' · '+j.title+' · '+timePair(PublisherTime.inputISO(f.elements.at.value),j.page_id);}catch{$('#reschedule-info').textContent='Chọn ngày giờ Việt Nam hợp lệ.';}}
document.addEventListener('click',e=>{const id=e.target.dataset.reschedule;if(id)openRescheduler(id);});
function openRescheduler(id){const j=state.jobs.find(x=>x.id===id),f=$('#reschedule-form');if(!j)return;f.elements.id.value=id;f.elements.at.value=PublisherTime.inputValue(j.scheduled_at);rescheduleComparison();$('#rescheduler').showModal();}
$('#reschedule-form').elements.at.oninput=rescheduleComparison;
$('#close-reschedule').onclick=()=>$('#rescheduler').close();$('#reschedule-form').onsubmit=e=>{e.preventDefault();guard(async()=>{const b=Object.fromEntries(new FormData(e.target));b.at=PublisherTime.inputISO(b.at);await api('/api/reschedule',b);$('#rescheduler').close();await refresh();notice('Đã đổi giờ đăng nội bộ. Telegram sẽ báo khi bài đăng thành công.');});};
$('#discover-country').onchange=()=>$('#discover-zone').value=PublisherTime.zone;
$('#discover-form').onsubmit=e=>{e.preventDefault();guard(async()=>{const button=e.target.querySelector('button');button.disabled=true;button.textContent='Đang đọc từ Meta…';try{const result=await api('/api/discover',Object.fromEntries(new FormData(e.target)));e.target.reset();discoverySession=result.session;$('#discovered').innerHTML=result.pages.length?'<p class="hint">Chọn Page cần kết nối. Page đã có giữ nguyên múi giờ và khung giờ.</p>'+result.pages.map(p=>`<label class="discover-page"><input type="checkbox" value="${esc(p.id)}" ${p.available?'':'disabled'}><span><b>${esc(p.name)}</b><small>${esc(p.id)} ${p.existing?'· Đã có trong workspace':''}${p.available?'':'· Meta chưa cấp token'}</small></span></label>`).join(''):'<div class="empty"><b>Meta chưa trả Page nào</b>Kiểm tra pages_show_list, quyền quản lý Page và danh sách tài sản được cấp cho App.</div>';$('#connect-selected').hidden=!result.pages.length;if(result.truncated)notice('Đã đọc tối đa 1.000 Page; hãy dùng token giới hạn tài sản nếu cần tìm Page khác.');}finally{button.disabled=false;button.textContent='Đọc danh sách Page →';}});};
$('#connect-selected').onclick=()=>guard(async()=>{const button=$('#connect-selected');button.disabled=true;try{const ids=[...document.querySelectorAll('#discovered input:checked')].map(x=>x.value);const b=await api('/api/connect-pages',{session:discoverySession,ids,country:$('#discover-country').value,zone:$('#discover-zone').value,slots:$('#discover-slots').value.split(',').map(x=>x.trim()).filter(Boolean)});$('#discovered').innerHTML='';button.hidden=true;discoverySession=null;await refresh();navigate('pages');notice('Đã kết nối '+b.count+' Page. Kiểm tra khung giờ và thông tin quyền trước khi đăng.');}finally{button.disabled=false;}});

$('#clear-job-date').onclick=()=>{$('#job-date').value='';renderJobs();};
// Keep the comparison adjacent to the time input, including on narrow screens.
$('#manual-wrap').firstChild.textContent='Ngày giờ Việt Nam (UTC+7)';
$('#reschedule-form').elements.at.parentElement.firstChild.textContent='Ngày giờ Việt Nam (UTC+7)';
const comparison=document.createElement('p');comparison.id='manual-comparison';comparison.className='hint';$('#manual-wrap').append(comparison);
manualComparison();
