// Page-owned uploads and stock. Legacy, unassigned videos stay separate.
const libraryControls=document.createElement('div');libraryControls.className='page-upload-controls';libraryControls.innerHTML='<label>Kho video / Page nhận file<select id="library-page" aria-label="Kho video theo Page"></select></label><label class="check-row"><input id="library-auto" type="checkbox" checked> Tự xếp video theo thứ tự tên file vào khung giờ sắp tới sau khi tải lên</label><p class="hint">Chọn Page trước khi nhập MP4 + TXT cùng tên. Caption và Comment 1 được đọc từ TXT. Lịch chỉ nằm trong tool; đến giờ mới tải lên Facebook.</p>';
$('#library article').append(libraryControls);
const progress=document.createElement('article');progress.innerHTML='<div class="row"><h2>Tiến trình từng Page</h2><select id="progress-page" aria-label="Tổng quan theo Page"></select></div><div id="page-progress"></div>';
$('#overview').prepend(progress);
const pageDialog=document.createElement('dialog');pageDialog.id='page-workspace';pageDialog.innerHTML='<div class="row"><h2 id="workspace-title">Cài đặt Page</h2><button id="close-workspace" class="secondary">Đóng</button></div><p id="workspace-stock"></p><label class="button">＋ Tải MP4 + TXT / ZIP cho Page<input type="file" id="page-files" accept=".mp4,.txt,.zip" multiple hidden></label><label class="check-row"><input id="page-auto" type="checkbox" checked> Tự xếp vào các khung giờ sắp tới sau khi tải lên</label><p class="hint">File 1, 2, 3… được xếp theo thứ tự tên; khung đã có bài sẽ được bỏ qua. Không đăng bù vào giờ đã qua. Đến giờ mới upload và đăng ngay qua API.</p><h3>Khung giờ đăng hằng ngày · giờ Việt Nam</h3><label>Ngày đối chiếu (giờ địa phương đổi theo ngày/DST)<input type="date" id="slot-date"></label><div id="slot-grid" class="slot-grid"></div><label>Khung giờ thêm (HH:mm, cách nhau bằng dấu phẩy)<input id="extra-slots" placeholder="Ví dụ: 09:15, 20:45"></label><button id="save-slots">Lưu khung giờ</button><p class="hint">Tối đa 12 khung. Chỉ áp dụng cho lịch mới, không đổi giờ các bài đã xác nhận.</p><div class="row"><h3>Video của Page</h3><button id="queue-page-videos" class="secondary">Xếp các video chưa có lịch</button></div><div id="workspace-videos"></div>';
document.body.append(pageDialog);
let workspacePage=null;
function populatePageFilter(el,first,unassigned=false){const value=el.value;el.innerHTML=`<option value="">${first}</option>`+(unassigned?'<option value="unassigned">Chưa gán Page (video cũ)</option>':'')+state.pages.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');el.value=value;}
function pageTotals(p){const assets=state.assets.filter(a=>a.page_id===p.id),jobs=state.jobs.filter(j=>j.page_id===p.id);return {assets,jobs,published:jobs.filter(j=>j.published_at).length,waiting:jobs.filter(j=>['scheduled','starting','uploading','finishing','checking'].includes(j.status)).length,issues:jobs.filter(j=>['failed','review','missed'].includes(j.status)).length};}
function canPublishNow(a){const j=state.jobs.find(j=>j.page_id===a.page_id&&j.asset_id===a.id&&j.status!=='cancelled');return a.page_id&&(!j||(j.status==='scheduled'&&!j.video_id));}
function renderPageSettingsButtons(){document.querySelectorAll('#pages-list .page-card').forEach((card,i)=>{const b=document.createElement('button');b.className='secondary compact';b.textContent='Cài đặt · Video & giờ đăng';b.onclick=()=>openPageWorkspace(state.pages[i].id);card.querySelector('.actions').prepend(b);});}
function renderPageWorkspace(){
 populatePageFilter($('#library-page'),'Tất cả kho · chọn Page trước khi nhập',true);populatePageFilter($('#progress-page'),'Tất cả Page');
 const pages=state.pages.filter(p=>!$('#progress-page').value||p.id===$('#progress-page').value);
 $('#page-progress').innerHTML='<div class="table-scroll"><table><thead><tr><th>Page</th><th>Kho</th><th>Chờ đăng / đang xử lý</th><th>Đã đăng</th><th>Chưa đăng còn lại</th><th>Cần xử lý</th><th>Tiếp theo</th><th></th></tr></thead><tbody>'+pages.map(p=>{const t=pageTotals(p),next=t.jobs.filter(j=>j.status==='scheduled').sort((a,b)=>a.scheduled_at.localeCompare(b.scheduled_at))[0];return `<tr><td>${esc(p.name)}</td><td>${t.assets.length}</td><td>${t.waiting}</td><td>${t.published}</td><td><span class="pill ${p.remaining<=3?'warn':''}">${p.remaining} ${p.remaining<=3?'· Cần bổ sung':''}</span></td><td>${t.issues}</td><td>${next?esc(timePair(next.scheduled_at,p.id)):'Chưa có lịch'}</td><td><button class="text-button" data-workspace="${p.id}">Cài đặt / tải video</button></td></tr>`;}).join('')+'</tbody></table></div>';
 if(workspacePage&&pageDialog.open)renderWorkspaceVideos();
}
async function uploadPageFiles(files,pageId,auto){
 if(!pageId||pageId==='unassigned')throw Error('Hãy chọn đúng Page nhận video trước khi tải file.');if(!files.length)return;
 const form=new FormData();form.append('pageId',pageId);form.append('autoSchedule',String(auto));for(const file of files)form.append('files',file);
 $('#import-note').textContent='Đang nhập MP4 + TXT vào Page…';
 const b=await api('/api/import',form);await refresh();renderPageWorkspace();
 notice(`Đã nhập ${b.imported} video vào ${state.pages.find(p=>p.id===pageId)?.name}. Đã xếp ${b.scheduled} lịch nội bộ.${b.warnings.length?'\n'+b.warnings.join('\n'):''}`);
 $('#import-note').textContent=`Đã nhập ${b.imported} video · ${b.scheduled} lịch.`;
}
function openPageWorkspace(id){workspacePage=id;$('#workspace-notice')?.remove();const p=state.pages.find(p=>p.id===id);$('#workspace-title').textContent='Cài đặt · '+p.name;$('#slot-date').value=PublisherTime.inputValue(new Date()).slice(0,10);$('#extra-slots').value='';renderSlotGrid();renderWorkspaceVideos();pageDialog.showModal();}
function renderSlotGrid(){const p=state.pages.find(p=>p.id===workspacePage);if(!p)return;$('#slot-grid').innerHTML=PublisherTime.slotRows(p.slots).map((s,i)=>`<div class="slot-option" data-slot-hour="${s.hour}"><input type="checkbox" aria-label="Chọn giờ ${s.time} Việt Nam" value="${s.time}" ${s.selected?'checked':''}><span><span class="slot-editor"><b>${s.hour}:</b><select aria-label="Phút cho giờ ${s.hour} (khung ${i+1})">${Array.from({length:60},(_,m)=>String(m).padStart(2,'0')).map(m=>`<option value="${m}" ${m===s.minute?'selected':''}>${m}</option>`).join('')}</select><b>VN</b></span><small data-slot-local></small></span></div>`).join('');updateSlotComparisons();}
function updateSlotComparisons(){for(const card of document.querySelectorAll('#slot-grid .slot-option')){const input=card.querySelector('input'),time=card.dataset.slotHour+':'+card.querySelector('select').value;input.value=time;input.setAttribute('aria-label','Chọn giờ '+time+' Việt Nam');try{card.querySelector('[data-slot-local]').textContent=timePair(PublisherTime.inputISO($('#slot-date').value+'T'+time),workspacePage).split(' ↔ ')[1];}catch{card.querySelector('[data-slot-local]').textContent='Chọn ngày đối chiếu hợp lệ.';}}}
$('#slot-grid').onchange=e=>{if(e.target.matches('select')){e.target.closest('.slot-option').querySelector('input').checked=true;updateSlotComparisons();}};
$('#slot-grid').onclick=e=>{if(e.target.closest('select,input'))return;const card=e.target.closest('.slot-option');if(card){const c=card.querySelector('input');c.checked=!c.checked;}};
function renderWorkspaceVideos(){const p=state.pages.find(p=>p.id===workspacePage);if(!p)return;$('#workspace-stock').textContent=`${p.name} · còn ${p.remaining} video chưa đăng${p.remaining<=3?' — gần hết, hãy gen và nhập thêm.':''}`;
 const assets=state.assets.filter(a=>a.page_id===p.id).sort((a,b)=>a.name.localeCompare(b.name,'en',{numeric:true}));
 $('#workspace-videos').innerHTML=assets.length?assets.map(a=>{const j=state.jobs.find(j=>j.page_id===p.id&&j.asset_id===a.id&&j.status!=='cancelled');return `<div class="mini-item"><b>${esc(a.title||a.name)}</b><small>${esc(a.name)} · ${a.caption?'Có caption':'Thiếu caption'} · ${a.comment?'Có Comment 1':'Không Comment 1'}</small><small>${j?`${labels[j.status]} · ${esc(timePair(j.scheduled_at,p.id))}`:'Chưa xếp lịch'}</small><div class="actions"><button class="text-button" data-inspect-asset="${a.id}">Xem caption / Comment 1</button>${!j||j.status==='scheduled'?`<button class="secondary compact" data-publish-now="${a.id}">Đăng ngay</button>`:''}</div></div>`;}).join(''):'<div class="empty"><b>Page chưa có video</b>Tải các cặp MP4 + TXT cùng tên ở trên để bắt đầu.</div>';
}
$('#library-page').onchange=()=>{selected.clear();assetPage=1;invalidate();if(state.pages.some(p=>p.id===$('#library-page').value)){$('#target-page').value=$('#library-page').value;pageInfo();manualComparison();}renderAssets();renderStats();};
$('#progress-page').onchange=renderPageWorkspace;
$('#page-progress').onclick=e=>{if(e.target.dataset.workspace)openPageWorkspace(e.target.dataset.workspace);};
$('#close-workspace').onclick=()=>pageDialog.close();
$('#page-files').onchange=()=>guard(async()=>{await uploadPageFiles($('#page-files').files,workspacePage,$('#page-auto').checked);$('#page-files').value='';});
$('#slot-date').onchange=updateSlotComparisons;
$('#save-slots').onclick=()=>guard(async()=>{const p=state.pages.find(p=>p.id===workspacePage),slots=[...document.querySelectorAll('#slot-grid input:checked')].map(e=>e.value).concat($('#extra-slots').value.split(',').map(s=>s.trim()).filter(Boolean));await api('/api/pages',{id:p.id,name:p.name,country:p.country,zone:PublisherTime.zone,slots});await refresh();renderSlotGrid();notice('Đã lưu khung giờ Việt Nam cho '+p.name+'. Lịch cũ không bị thay đổi.');});
$('#queue-page-videos').onclick=()=>guard(async()=>{const b=await api('/api/page-queue',{pageId:workspacePage});await refresh();notice('Đã xếp '+b.count+' video vào các khung giờ sắp tới.');});
document.addEventListener('click',e=>guard(async()=>{
 const id=e.target.dataset.publishNow;if(id){const a=state.assets.find(a=>a.id===id),p=state.pages.find(p=>p.id===a.page_id);if(!p)throw Error('Video chưa được gán Page.');if(!a.caption?.trim())throw Error('Bổ sung caption trước khi đăng.');
  if(!confirm(`ĐĂNG THẬT NGAY\nPage: ${p.name}\nVideo: ${a.title||a.name}\nCaption: ${a.caption}\nComment 1: ${a.comment||'(không có)'}\nLịch chờ của video này (nếu có) sẽ chuyển sang đăng ngay. Xác nhận?`))return;
  await api('/api/publish-now',{assetId:a.id,pageId:p.id});await refresh();renderAssets();notice('Đã gửi video vào hàng đợi đăng ngay · '+p.name+'. Chỉ đánh dấu thành công khi Meta xác nhận.');
 }
 const inspect=e.target.dataset.inspectAsset;if(inspect){pageDialog.close();navigate('library');$('#library-page').value=workspacePage;renderAssets();const a=state.assets.find(a=>a.id===inspect),f=$('#asset-form');for(const k of ['id','title','caption','comment'])f.elements[k].value=a[k]||'';$('#video').src='/media/'+a.id;$('#editor').showModal();}
}));

let studioState={links:[]};
const studioPanel=document.createElement('article');studioPanel.innerHTML='<div class="row"><div><h2>Gen video → Tự xếp lịch</h2><p>Giữ nguyên Studio cũ và cấu hình Page. Lô hoàn tất sẽ tự chuyển MP4 + caption + Comment 1 sang đúng Page.</p></div><a class="button" href="http://localhost:3020/render" target="_blank" rel="noopener">＋ Gen video · Studio</a></div><div id="studio-links"></div><button id="studio-sync" class="secondary">Kiểm tra lô đã gen xong</button><p class="hint">Chỉ Page đã liên kết và bật tự nhận mới tự chuyển. Các Page khác vẫn gen tay bình thường. Không nhập lại lô cũ trước lúc bật liên kết; lô cũ chỉ được chuyển khi chọn riêng.</p>';
$('#overview').prepend(studioPanel);
const studioInPage=document.createElement('div');studioInPage.innerHTML='<div class="row"><a id="workspace-studio" class="button" target="_blank" rel="noopener">Gen video cho Page này ↗</a><label class="check-row"><input id="workspace-studio-auto" type="checkbox"> Tự nhận lô gen mới và xếp lịch</label></div><p id="workspace-studio-state" class="hint"></p>';
pageDialog.insertBefore(studioInPage,$('#workspace-stock'));
async function refreshStudio(){studioState=await api('/api/studio-bridge');$('#studio-links').innerHTML=studioState.links.map(l=>`<div class="mini-item"><div class="row"><b>${esc(l.name)}</b><a class="button secondary compact" href="http://localhost:3020/render?page=${encodeURIComponent(l.studio_page_id)}" target="_blank" rel="noopener">Gen video ↗</a></div><small>${l.enabled?'Tự chuyển: BẬT':'Gen tay: tự chuyển TẮT'} · Đã nhận ${l.imported} video${l.error?' · Lỗi: '+esc(l.error):''}</small></div>`).join('')||'<p class="hint">Chưa có Page liên kết.</p>';if(workspacePage)renderStudioInPage();}
function renderStudioInPage(){const link=studioState.links.find(l=>l.page_id===workspacePage);studioInPage.hidden=!link;if(!link)return;$('#workspace-studio').href='http://localhost:3020/render?page='+encodeURIComponent(link.studio_page_id);$('#workspace-studio-auto').checked=!!link.enabled;$('#workspace-studio-state').textContent=(link.error?'Lỗi chuyển lô: '+link.error:`Đã nhận ${link.imported} video. Kiểm tra lô hoàn tất mỗi 10 giây.`)+' Tắt tự nhận nếu muốn chỉ gen tay cho Page này; bật lại chỉ nhận các lô bắt đầu sau lúc bật.';}
const openPageWorkspaceBeforeStudio=openPageWorkspace;
openPageWorkspace=id=>{openPageWorkspaceBeforeStudio(id);renderStudioInPage();};
$('#workspace-studio-auto').onchange=()=>guard(async()=>{await api('/api/studio-bridge',{action:'toggle',pageId:workspacePage,enabled:$('#workspace-studio-auto').checked});await refreshStudio();notice('Đã cập nhật chế độ chuyển video Studio của Page.');});
$('#studio-sync').onclick=()=>guard(async()=>{const result=await api('/api/studio-bridge',{action:'sync'});await refresh();await refreshStudio();notice(`Đã chuyển thêm ${result.imported||0} video từ Studio. Xem lỗi từng Page nếu có.`);});
guard(refreshStudio);
setInterval(()=>refreshStudio().catch(()=>{}),15000);

// Video-first library: keep manual controls available without consuming a sidebar.
const libraryLayout=$('#library .workspace');libraryLayout.classList.add('library-workspace');
const manualPlanner=document.createElement('details');manualPlanner.className='manual-tools';manualPlanner.innerHTML='<summary>Xếp lịch thủ công · chỉ video chưa có lịch</summary>';
manualPlanner.append($('#library .planner'));$('#library .library-panel').before(manualPlanner);libraryLayout.querySelector('aside').remove();
const importArticle=$('#library article'),importDetails=document.createElement('details');importDetails.className='manual-tools';importDetails.innerHTML='<summary>Nhập MP4 + TXT / ZIP thủ công</summary>';importArticle.before(importDetails);importDetails.append(importArticle);
const libraryPageLabel=$('#library-page').parentElement;$('#library .library-panel .filters').prepend(libraryPageLabel);
const oldSelectionInfo=selectionInfo;selectionInfo=()=>{oldSelectionInfo();if(selected.size)manualPlanner.open=true;};
function assetHasJob(a){return state.jobs.some(j=>j.asset_id===a.id&&j.status!=='cancelled');}
function assetSchedule(a){const jobs=state.jobs.filter(j=>j.asset_id===a.id&&j.status!=='cancelled');return jobs.length?jobs.map(j=>`<div class="asset-schedule"><span class="pill ${j.published_at?'ok': ['failed','review','missed'].includes(j.status)?'warn':''}">${esc(labels[j.status]||j.status)}</span><b>${esc(PublisherDashboard.time24(PublisherDashboard.stamp(j)))} VN · ${esc(PublisherDashboard.dayKey(PublisherDashboard.stamp(j)).slice(5).split('-').reverse().join('/'))}</b><small>${esc(timePair(PublisherDashboard.stamp(j),j.page_id).split(' ↔ ')[1])}</small>${['scheduled','missed'].includes(j.status)?`<button class="text-button" data-reschedule="${j.id}">Đổi giờ video này</button>`:''}</div>`).join(''):'<div class="asset-schedule unplanned">Chưa có lịch · chọn video để xếp lịch</div>';}

// One Page filter governs progress, charts and the seven-day / 24-hour calendar.
const dashboardToolbar=document.createElement('article');dashboardToolbar.className='dashboard-toolbar';dashboardToolbar.innerHTML='<div><h2>Tổng quan đăng video</h2><p class="hint">Chọn tất cả Page hoặc một Page · số liệu và lịch theo giờ Việt Nam</p></div><label>Page hiển thị</label>';
dashboardToolbar.lastElementChild.append($('#progress-page'));$('#overview').prepend(dashboardToolbar);
const chartPanel=document.createElement('article');chartPanel.innerHTML='<div class="row"><div><h2>Biểu đồ video đăng</h2><p class="hint">Đã đăng tính theo thời điểm Meta xác nhận; lịch chờ được hiển thị riêng.</p></div><div class="chart-controls"><select id="chart-period" aria-label="Biểu đồ theo ngày hoặc tháng"><option value="day">Theo ngày trong tháng</option><option value="month">Theo tháng trong năm</option></select><input type="month" id="chart-month" aria-label="Tháng thống kê"><input type="number" id="chart-year" min="2000" max="2100" aria-label="Năm thống kê" hidden></div></div><div id="chart-summary" class="chart-summary"></div><div class="chart-legend"><span>● Đã đăng</span><span>● Chờ / đang đăng</span></div><div id="publish-chart" class="publish-chart"></div><details><summary>Xem bảng số liệu</summary><div id="chart-table" class="table-scroll"></div></details>';
dashboardToolbar.after(chartPanel);
const weekArticle=$('#week-strip').closest('article');chartPanel.after(weekArticle);
weekArticle.querySelector('h2').textContent='Lịch video · 7 ngày phía trước';
const weekControls=document.createElement('div');weekControls.className='calendar-controls';weekControls.innerHTML='<button id="week-back" class="secondary compact" aria-label="Tuần trước">← 7 ngày</button><input type="date" id="week-start" aria-label="Ngày bắt đầu lịch 7 ngày"><button id="week-today" class="secondary compact">Hôm nay</button><button id="week-forward" class="secondary compact" aria-label="Tuần tiếp theo">7 ngày →</button><select id="calendar-page" aria-label="Page trong lịch 7 ngày"></select>';
$('#week-strip').before(weekControls);
const timeline=document.createElement('div');timeline.innerHTML='<div class="row timeline-heading"><h3>Video theo khung 24 giờ · Việt Nam</h3><input type="date" id="timeline-day" aria-label="Ngày xem lịch 24 giờ"></div><p id="timeline-summary" class="hint"></p><div class="timeline-scroll"><div id="timeline-hours"></div></div>';
$('#week-strip').after(timeline);
const currentDashboardDay=PublisherDashboard.dayKey(new Date());$('#week-start').value=currentDashboardDay;$('#timeline-day').value=currentDashboardDay;$('#chart-month').value=currentDashboardDay.slice(0,7);$('#chart-year').value=currentDashboardDay.slice(0,4);
// Keep setup/help available, but let the calendar and chart lead the overview.
$('#overview .welcome-card')?.remove();
const compactStudio=document.createElement('details');compactStudio.className='studio-compact';compactStudio.innerHTML='<summary>Gen video & kết nối tự động Studio · mở khi cần</summary>';studioPanel.before(compactStudio);compactStudio.append(studioPanel);
function dashboardPage(){return $('#progress-page')?.value||'';}
function dashboardJobs(){return PublisherDashboard.jobsFor(state.jobs,dashboardPage());}
let timelineRenderKey='';
function renderCalendarDashboard(){
 if(!$('#timeline-day'))return;
 const jobs=dashboardJobs(),start=$('#week-start').value||PublisherDashboard.dayKey(new Date()),day=$('#timeline-day').value||start;
 $('#calendar-page').innerHTML='<option value="">Tất cả Page</option>'+state.pages.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('#calendar-page').value=dashboardPage();
 $('#week-zone').textContent=(state.pages.find(p=>p.id===dashboardPage())?.name||'Tất cả Page')+' · giờ Việt Nam (24h)';
 $('#week-strip').innerHTML=Array.from({length:7},(_,i)=>{const key=PublisherDashboard.addDays(start,i),items=jobs.filter(j=>PublisherDashboard.dayKey(PublisherDashboard.stamp(j))===key),posted=items.filter(j=>j.published_at).length;return `<button class="week-day ${key===day?'active-day':''}" data-day="${key}"><span>${key===PublisherDashboard.dayKey(new Date())?'Hôm nay':new Date(key+'T00:00:00Z').toLocaleDateString('vi-VN',{weekday:'short',timeZone:'UTC'})}</span><b>${key.slice(8)}/${key.slice(5,7)}</b><small>${items.length} video</small><small>${posted} đã đăng</small></button>`;}).join('');
 const rows=PublisherDashboard.hours(state.jobs,day,dashboardPage()),count=rows.reduce((n,r)=>n+r.jobs.length,0);
 $('#timeline-summary').textContent=`${day.slice(8)}/${day.slice(5,7)} · ${count} video · ${state.pages.find(p=>p.id===dashboardPage())?.name||'Tất cả Page'} · bấm video để xem, Đổi giờ để chỉnh lịch.`;
 $('#timeline-hours').innerHTML=rows.map(r=>`<div class="timeline-row"><b class="hour-label">${r.hour}</b><div class="hour-videos">${r.jobs.length?r.jobs.map(j=>`<div class="timeline-video ${j.published_at?'published':''}"><button class="timeline-preview" data-preview-asset="${j.asset_id}" aria-label="Xem video ${esc(j.title)}"><video src="/media/${j.asset_id}#t=0.1" muted preload="metadata"></video></button><div><b>${esc(PublisherDashboard.time24(PublisherDashboard.stamp(j)))} · ${esc(j.title||'Video')}</b><small>${esc(j.page_name)}</small><small>${esc(timePair(PublisherDashboard.stamp(j),j.page_id).split(' ↔ ')[1])}</small><span class="pill ${j.published_at?'ok':''}">${esc(labels[j.status]||j.status)}</span><div class="actions"><button class="text-button" data-preview-asset="${j.asset_id}">Xem video</button>${['scheduled','missed'].includes(j.status)?`<button class="text-button" data-reschedule="${j.id}">Đổi giờ</button>`:''}</div></div></div>`).join(''):'<span class="empty-hour">—</span>'}</div></div>`).join('');
 const renderKey=day+'|'+dashboardPage();if(renderKey!==timelineRenderKey){timelineRenderKey=renderKey;const index=rows.findIndex(r=>r.jobs.length);requestAnimationFrame(()=>{const box=$('.timeline-scroll'),row=$('#timeline-hours').children[Math.max(0,index)];box.scrollTop=row.offsetTop-$('#timeline-hours').offsetTop;});}
 renderPublishChart();
}
function renderPublishChart(){
 const period=$('#chart-period').value,month=$('#chart-month').value||PublisherDashboard.dayKey(new Date()).slice(0,7),year=Number($('#chart-year').value);
 if(!Number.isInteger(year)||year<2000||year>2100)return;
 const bins=PublisherDashboard.series(state.jobs,{pageId:dashboardPage(),period,month,year}),posted=bins.reduce((n,b)=>n+b.published,0),waiting=bins.reduce((n,b)=>n+b.waiting,0),max=Math.max(1,...bins.flatMap(b=>[b.published,b.waiting])),step=920/bins.length;
 $('#chart-summary').textContent=`${state.pages.find(p=>p.id===dashboardPage())?.name||'Tất cả Page'} · ${period==='day'?month.split('-').reverse().join('/'):year} · ${posted} đã đăng · ${waiting} chờ / đang đăng`;
 $('#publish-chart').innerHTML=`<svg viewBox="0 0 1000 250" role="img" aria-label="Biểu đồ: ${posted} video đã đăng, ${waiting} video chờ hoặc đang đăng"><line x1="45" y1="205" x2="980" y2="205" stroke="#d7dfed"/><line x1="45" y1="25" x2="980" y2="25" stroke="#edf1f7"/><text x="6" y="30" fill="#64748b" font-size="13">${max}</text><text x="20" y="209" fill="#64748b" font-size="13">0</text>${bins.map((b,i)=>{const x=50+i*step,w=Math.max(3,step*.32);return `<g><title>${esc(b.key)}: ${b.published} đã đăng, ${b.waiting} chờ</title><rect x="${x}" y="${205-175*b.published/max}" width="${w}" height="${175*b.published/max}" rx="3" fill="#245ee8"/><rect x="${x+w+2}" y="${205-175*b.waiting/max}" width="${w}" height="${175*b.waiting/max}" rx="3" fill="#b9cae9"/><text x="${x+step*.33}" y="228" text-anchor="middle" fill="#64748b" font-size="12">${b.label}</text></g>`;}).join('')}</svg>`;
 $('#chart-table').innerHTML='<table><thead><tr><th>Ngày / tháng</th><th>Đã đăng</th><th>Chờ / đang đăng</th></tr></thead><tbody>'+bins.map(b=>`<tr><td>${esc(b.key)}</td><td>${b.published}</td><td>${b.waiting}</td></tr>`).join('')+'</tbody></table>';
}
$('#progress-page').onchange=()=>{renderPageWorkspace();renderStats();renderOverview();};
$('#chart-period').onchange=()=>{$('#chart-month').hidden=$('#chart-period').value==='month';$('#chart-year').hidden=$('#chart-period').value!=='month';renderPublishChart();};
$('#chart-month').onchange=renderPublishChart;$('#chart-year').oninput=renderPublishChart;
$('#week-start').onchange=()=>{if(!$('#week-start').value)return;$('#timeline-day').value=$('#week-start').value;renderCalendarDashboard();};
for(const [id,offset] of [['week-back',-7],['week-forward',7]])$('#'+id).onclick=()=>{$('#week-start').value=PublisherDashboard.addDays($('#week-start').value,offset);$('#timeline-day').value=$('#week-start').value;renderCalendarDashboard();};
$('#week-today').onclick=()=>{$('#week-start').value=PublisherDashboard.dayKey(new Date());$('#timeline-day').value=$('#week-start').value;renderCalendarDashboard();};
$('#calendar-page').onchange=()=>{$('#progress-page').value=$('#calendar-page').value;$('#progress-page').onchange();};
weekArticle.querySelector('[data-goto="queue"]').onclick=e=>{e.stopPropagation();$('#job-page').value=dashboardPage();$('#job-date').value='';$('#job-search').value='';$('#job-filter').value='all';navigate('queue');renderJobs();};
$('#timeline-day').onchange=()=>{const day=$('#timeline-day').value,start=$('#week-start').value;if(!day)return;if(day<start||day>PublisherDashboard.addDays(start,6))$('#week-start').value=day;renderCalendarDashboard();};
document.addEventListener('click',e=>{const id=e.target.closest('[data-preview-asset]')?.dataset.previewAsset;if(!id)return;const a=state.assets.find(a=>a.id===id);if(!a)return;const f=$('#asset-form');for(const k of ['id','title','caption','comment'])f.elements[k].value=a[k]||'';$('#video').src='/media/'+a.id;$('#editor').showModal();});
